"""Report measured Stage1 outcomes; never manufacture unexecuted detector metrics."""
import sys,json,csv
from pathlib import Path
EXP=Path(__file__).resolve().parent;sys.path.insert(0,str(EXP))
from log_parsing_error_severity import load,save
ROOT=EXP/'results_phase3/strong_downstream_preflight';REPORT=EXP/'reports/strong_downstream_pilot.md'

def main():
    rr={s:load(ROOT/f'{s}.json') for s in ['HDFS','BGL']};refs=load(ROOT/'reference_manifest.json');config=load(EXP/'configs/strong_downstream_pilot.json')
    out=['# Strong downstream anomaly-detector pilot\n','**Status: Stage1 executed; Stage2 not run; expansion not justified.** This is a measured feasibility result, not a negative trained-detector result. The task arrived23:02UTC, after the recorded22:30 long-job cutoff; hard shutdown23:15UTC. No model training, embeddings, parser generation or arbitrary split search was run.\n',
    '## Questions and protocol\n','Does failure-prediction review recover downstream anomaly detection better than frequency-first? Supporting questions distinguish template text, final event partitions, sequential/contextual/semantic detector inputs, and review cost. Existing parser/review/audit results are preserved.\n',
    'Protocol was recorded in PROGRESS.md before computation. New outputs use `results_phase3/strong_downstream_preflight/` and `data/strong_downstream_preflight/`, separate from earlier downstream/audit reports. Source hashes, full raw-file digests, raw LineIds, unit members and split hashes are saved. Every covered raw line was checked against structured content and stored GT, and Drain assignments were asserted equal to saved groups. All conditions share exact units.\n',
    'We scanned the entire available HDFS andBGL raw files, not just the cached prefix. Existing parser artifacts cover only50,000 lines per system. A fully covered HDFS block must have every occurrence in that prefix, deduplicating repeated IDs within a line. A block spanning raw-line split boundaries is purged; raw line overlap across splits is asserted absent. BGL uses20-line nonoverlapping windows with any-alert aggregation. These are window labels, not line labels. Normal-only detector training would exclude anomalous training units.\n',
    'Frozen boundaries are60%/20%/20% of covered raw-line indices (0,30000,40000,50000), before inspecting labels. We did not move them after observing missing classes. Whole-session chronological placement differs from splitting a list of truncated prefix blocks. No test labels create predictor features, tune detector choices, or select a review ranking.\n',
    '## Reference paper and implementations\n',
    'Sun et al., DOI [10.1016/j.jss.2026.113161](https://asi.cs.cityu.edu.hk/paper/JSS_j.jss.2026.113161.pdf), §4.7,§5.2,§7: sessions where identifiers exist; otherwise20-event windows, stride10, any-anomaly aggregation; chronological60/20/20 split. Expert corrections affect training and test representations and form an upper-bound intervention. We deliberately use nonoverlapping BGL windows to avoid shared lines across splits. Expert subjectivity, correction realism and indirect interpretation of distinguishability limit comparison. Their detector suite is not reproduced here; the PDF does not supply a complete executable architecture/hyperparameter manifest.\n',
    'Pinned source snapshots and hashes are persisted in `reference_sources/` and `reference_manifest.json`. LogBERT’s author code uses masked log-event modeling and a hypersphere objective; a small generic Transformer would not constitute faithful reproduction. Logdeep provides a useful DeepLog-style LSTM reference. Its `robustlog` implementation is a unidirectional last-state LSTM without attention: it is **not** the attention/Bi-LSTM architecture described in the [LogRobust paper](https://www.microsoft.com/en-us/research/publication/robust-log-based-anomaly-detection-on-unstable-log-data/). We reject silently calling that substitute LogRobust. No pretrained word vectors were downloaded.\n']
    def table(h,rows):
        out.extend(['| '+' | '.join(h)+' |','|'+'|'.join('---' for _ in h)+'|']);out.extend('| '+' | '.join(map(str,r))+' |' for r in rows);out.append('')
    table(['Reference','Pinned revision','Inspection status'],[[r['repo'],r.get('revision'),'; '.join(x['path']+(':missing' if 'error' in x else ':saved') for x in r.get('files',[]))] for r in refs])
    out.append('## Coverage and valid detection units\n')
    table(['Dataset','Full raw lines','Assigned parser lines','Coverage','Train normal/anomalous','Validation normal/anomalous','Test normal/anomalous'],[[s,a['total_raw_lines'],a['covered_lines'],f"{a['coverage_fraction']:.3%}"]+[f"{a['splits'][k]['normal']}/{a['splits'][k]['anomalous']}" for k in ['train','validation','test']] for s,a in rr.items()])
    h=rr['HDFS']['closure'];table(['HDFS closure diagnostic','Measured count'],[[k,v] for k,v in h.items() if k!='labels_sha256'])
    out.append('**HDFS is not a viable normal-training pilot in the stored coverage.** Of4088 prefix blocks,4049 are incomplete. Only39 are complete; all39 are anomalous. The frozen train/validation/test sets contain5/10/24 anomalies andzero normal blocks. The earlier4088 “sessions” were prefix fragments; those old PCA/N3 results are retained as prefix diagnostics, not reinterpreted as complete-block benchmark results. Retaining only complete blocks creates severe selection bias, favouring early-ending abnormal blocks, and cannot rescue this prefix.\n')
    out.append(f"Closing all prefix blocks needs at least{h['extra_line_ids_to_close_prefix_blocks']} additional distinct raw lines; the last needed line is{h['furthest_required_line_id']}. Those rows lack saved parser predictions. Parsing only these scattered rows would change the original online parser stream/history and must be documented; alternatively process a contiguous prefix through that line or define a new complete-session sampling protocol before outcomes. Full block membership is saved, so another full raw scan is unnecessary. BlockId joins cover every prefix block; that does not prove the separate label-source raw file is byte-identical to this Loghub-2.0 version.\n")
    out.append('**BGL’s frozen test set has no anomalies.** The500 test windows are all normal, despite33 anomalous validation windows and200 anomalous training windows. AUROC, anomaly recall and useful positive-class AP comparisons cannot be estimated here. A stronger model cannot repair missing test positives. The full raw file has332222 alert lines, so the limitation is coverage/split—not lack of anomalies in BGL generally. Changing the cut after observing this is not an acceptable confirmatory rescue.\n')
    out.append('## Real parser provenance and representations\n')
    table(['Dataset','Model','LLM calls','Queries','Labelled candidate insertions','Final origin lines','Exact candidate-content overlaps train/val/test'],[[s,m,v['calls'],v['queries'],v['candidate_insertions'],v['final_origin_lines'],'/'.join(str(v['candidate_content_overlap_by_split'][k]) for k in ['train','validation','test'])] for s,a in rr.items() for m,v in a['parser_provenance'].items()])
    out.append('AdaParser uses the original pipeline at232951a,32 labelled Loghub candidates/system, local Llama/Gemma backend, seed0/context8192. The JSON stores final template text per input row. We recovered all four original output CSVs and independently verified200000 row joins on LineId, Content and EventTemplate. Original EventId and final template string are bijective in each file: grouping by final strings therefore exactly recovers the actual final EventId partition. Original IDs and content hashes are persisted as sidecars, and saved D-state source digests match these parser outputs. No complete temporal assignment/revision history or uncovered full-data predictions are available. We do not reintroduce Drain groups. Labelled candidate content overlaps include held-out BGL rows: this must be treated as declared parser seed supervision, not a completely unseen end-to-end test. Exact duplicate-content hits are not proven distinct candidate rows, and their counts need not be bounded by32. Whole-prefix parser adaptation is transductive relative to detector splits; a future online deployment claim needs time-resolved assignments or a frozen parser.\n')
    out.append('**HDFS has zero GT-versus-real-parser headroom in these artifacts:** both models madezero LLM calls, all50000 lines have candidate ancestry, PA=1 and assignments matchGT exactly. Any deterministic detector given identical representations, splits and seed receives the same input. This is not evidence that LLM errors are harmless; there are no such errors here to test. Real pipeline execution and LLM-generated-template coverage are different.\n')
    rows=[];machine=[]
    for s,a in rr.items():
        for p,v in a['conditions'].items():
            rows.append([s,p,v['events'],f"{v['line_PA']:.5f}",f"{v['partition']['ARI']:.9f}",v['partition']['mixed_pred_groups'],v['partition']['split_gt_groups']])
            machine.append({'dataset':s,'parser':p,'PA':v['line_PA'],**v['partition']})
    table(['Dataset','Parser representation','Event strings','Strict line PA','ARI','Merged predicted groups','Split GT types'],rows)
    out.append('BGL AdaParser affects only2 GT event types through splitting, with no mixed-GT final groups, in either model. StrictPA≈99.5% and highARI leave little global partition change, but highARI alone cannot rule out rare consequential events. Drain/cache strictPA differs sharply while their partitions almost agree: text errors and event assignment errors must remain separate.\n')
    rows=[]
    for s,a in rr.items():
        for p in ['llama/AdaParser','gemma/AdaParser']:
            for split,v in a['conditions'][p]['split_diagnostics'].items():rows.append([s,p,split,v['units'],v['wrong_text_units'],v['word_changed_units'],v['unseen_event_units'] if a['splits']['train']['normal'] else 'NA: empty normal training'])
    table(['Dataset','Parser','Split','Units','Any wrong text','Any changed N3 word bag','Any normal-train OOV event'],rows)
    out.append('In BGL test, both parsers change text in6/500 windows and the N3 word bag in4/500; all are normal windows. That permits a future false-positive diagnostic only, not anomaly recovery/recall claims on this test. Word-bag changes are representation proxies, not verified semantic harm. HDFS OOV counts are uninterpretable because normal training is empty.\n')
    out.append('## Detector and review-stage status\n')
    table(['Detector family','Required input / supervision','Sensitivity being tested','Implementation/execution status'],[
    ['DeepLog-style','normal event-ID sequences','assignment merging/splitting, OOV','Pinned LSTM source; not integrated/trained'],['LogBERT','normal masked event sequences; hypersphere objective','context/event assignments','Author source pinned; not integrated/trained'],['LogRobust-style','semantic word vectors; labelled sequence training','template constants/semantic distortion','Faithful attention/Bi-LSTM implementation unresolved; not trained'],['PCA control','event count vectors','partition changes; invariant to bijective relabels','Existing prefix results preserved; no fit on invalid new split']])
    out.append('F1/AUPRC/recall/precision/AUROC/FPR, seed uncertainty, training/inference costs and review-budget curves are **not available for new strong detectors**. No zero-valued placeholder is reported. No recovery fraction is computed; HDFS haszero parser headroom andBGL haszero test positives. Five seeds cannot cure these validity failures. The Stage2 health/gap gate is untested; Stage1 prerequisites already fail, so Stage3 review expansion is not run.\n')
    out.append('Stored real-parser review histories provide Random/frequency/D×size/Oracle and source-layer states of each final template’s first line. Those D states come from zero-shot rules-template inputs, not AdaParser’s actual generation prompt. Static Clotho risk/risk×size and real-parser U histories are not present in the inspected artifacts. Capped U vectors predict that benchmark’s independent five-sample strict label; they cannot be silently attached to AdaParser’s final outcomes. Cached-parser U/D histories and the severity audit remain reusable only in their own mapped settings. Parser candidates cost32 labels common to policies; U target warm-start labels would be extra, and D source labels must also be disclosed.\n')
    out.append('One template-only review of a final AdaParser string affects its assigned line set; replacing it by majorityGT can coalesce equal strings but cannot split a mixed group into correct memberships. Grouping-aware correction is a separate intervention and requires verified line reassignment. Frozen-detector and retrained-detector scenarios are distinct. The saved configuration proposes retraining during offline commissioning, with common validation choices and no test tuning. Local downstream-oracle effects are non-additive and cannot be summed. No harm predictor is developed.\n')
    out.append('## Answers and smallest justified next step\n')
    table(['Question','Strongest supported answer'],[
    ['1. Do real AdaParser errors affect strong detectors?','Unknown: no valid trained pilot. Saved HDFS is exactlyGT; BGL test hasno anomalies.'],['2. Which families are sensitive?','Not measured. Event/context families can observe partition changes; semantic families can observe text changes, but neither guarantees useful detection.'],['3. Does predictor review beat frequency?','Not tested with strong detectors; existing weak-detector results cannot substitute.'],['4. Text versus grouping?','The distinction is measurable: HDFS identity, BGL two splitGT types; text-only reviews cannot be assumed to repair assignments.'],['5. Do U/D have downstream value?','No new evidence either way. Required aligned final-parser scores/valid downstream data are incomplete.'],['6. Develop a downstream-harm predictor?','Not justified yet; first establish detector health and observable parser headroom on valid held-out units.'],['7. Paper contribution?','A reproducible validity audit: incomplete-session selection, absent held-out anomalies, and candidate-perfect parser coverage can make downstream failure-prediction evaluation uninformative. No universal performance claim.']])
    out.append('Next session: define a new data protocol before outcomes using complete HDFS blocks and a broader chronological BGL horizon; do not pick a test interval for favourable anomaly counts. Recover additional parser outputs only for that matched protocol, with candidate overlap and adaptation history explicitly controlled. For HDFS, report that the current32-shot condition is candidate-perfect and include its LLM-generated subset only if nonempty. Before expensive parsing, GT-only detector health checks can determine whether the full data/session protocol supports meaningful detection; they do not establish parser gaps. Then run one sequence and one faithful semantic/contextual pilot, five seeds, with paired unit-cluster intervals. Expand review curves only after the stated gate passes.\n')
    out.append('## Reproduction and limitations\n')
    out.append('`configs/strong_downstream_pilot.json` freezes the inspected data protocol and candidate implementations; it is not a claim of an implemented/trained detector. Run `.venv/bin/python experiments/log_parsing_strong_downstream_preflight.py` with the existing secret environment and cached ZIPs/labels; it skips completed systems. Run `.venv/bin/python experiments/log_parsing_strong_downstream_validate.py` while original parser CSVs are present (validated sidecars survive in RESULTS_REPO). Then run `.venv/bin/python experiments/log_parsing_strong_downstream_report.py` and `.venv/bin/python experiments/paper/fig_strong_downstream_preflight.py`; `paper/table_strong_downstream_preflight.py` regenerates the comparison table. Full raw-file scans took about32s total; per-system results were uploaded as completed. Reference API/file downloads checked free disk first;15GiB was free and the L40S was idle. No new large data/model downloads occurred.\n')
    out.append('Limitations: only existing parser coverage is evaluated; candidate seeds and final-stream adaptation predate detector splits; original final EventIds and row content are verified but temporal assignment histories are not saved; strictGT may encode annotation conventions; proxy severity labels remain unverified; reference implementations are inspected, not reproduced; the session deadline independently prevents GPU training. No aggregate over two datasets or repeated seeds is presented as evidence of generalization. The earlier fixed-grouping/count results are preserved and do not answer this stronger question.\n')
    text='\n'.join(out)
    for before,after in {'Stage1':'Stage 1','Stage2':'Stage 2','Stage3':'Stage 3','arrived23':'arrived 23','recorded22':'recorded 22','shutdown23':'shutdown 23','andBGL':'and BGL','only50,000':'only 50,000','uses20':'uses 20','are60%':'are 60%','otherwise20':'otherwise 20','of4088':'of 4,088','blocks,4049':'blocks, 4,049','Only39':'Only 39','all39':'all 39','contain5/10/24':'contain 5/10/24','andzero':'and zero','earlier4088':'earlier 4,088','file has332222':'file has 332,222','with no':'with no','cost32':'cost 32','madezero':'made zero','all50000':'all 50,000','affects only2':'affects only 2','both parsers change text in6/500':'both parsers change text in 6/500','in4/500':'in 4/500','haszero':'has zero','about32s':'about 32s','first32':'first 32','uses the original pipeline at232951a,32':'uses the original pipeline at 232951a, 32','verified200000':'verified 200,000','exactlyGT':'exactly GT','last needed line is':'last needed line is ','at least':'at least '}.items():text=text.replace(before,after)
    REPORT.write_text(text);save(ROOT/'validation.json',{'systems':list(rr),'full_raw_lines_scanned':sum(a['total_raw_lines'] for a in rr.values()),'prefix_content_rows_asserted':100000,'no_cross_split_raw_line_overlap':all(a['no_cross_split_raw_line_overlap'] for a in rr.values()),'detector_training_executed':False,'stage1_gate_passed':False,'reasons':['HDFS has no complete normal training sessions','HDFS AdaParser is GT-identical and candidate-only','BGL frozen test has no anomalies','Long-job cutoff passed before task arrival'],'config_sha256':__import__('hashlib').sha256((EXP/'configs/strong_downstream_pilot.json').read_bytes()).hexdigest()})
    with (ROOT/'parser_comparison.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(machine[0]));w.writeheader();w.writerows(machine)
    print(REPORT)
if __name__=='__main__':main()
